import{_ as e,o as d,c as o,a2 as i}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"Mains (Hands)","description":"","frontmatter":{"title":"Mains (Hands)"},"headers":[],"relativePath":"en/reference/mains.md","filePath":"en/reference/mains.md"}'),a={name:"en/reference/mains.md"};function n(s,t,r,h,c,l){return d(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="mains-hands-acting-on-the-screen" tabindex="-1">Mains (Hands): acting on the screen <a class="header-anchor" href="#mains-hands-acting-on-the-screen" aria-label="Permalink to &quot;Mains (Hands): acting on the screen&quot;">​</a></h1><p>Mains produces synthetic input: pointer, keyboard, scrolling, windows. Every action goes through the same chain: point resolution, target probe, guard, ceiling gate, audit log, then execution. An action above the ceiling is refused.</p><h2 id="niveaux" tabindex="-1">Levels <a class="header-anchor" href="#niveaux" aria-label="Permalink to &quot;Levels {#niveaux}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Level</th><th>Internal name</th><th>Observed target required</th></tr></thead><tbody><tr><td><code>main_navigate</code></td><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>no</td></tr><tr><td><code>main_hover</code></td><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>no</td></tr><tr><td><code>main_activate</code></td><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>no</td></tr><tr><td><code>main_window_minimize</code></td><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>no</td></tr><tr><td><code>main_window_hide</code></td><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>no</td></tr><tr><td><code>main_window_show</code></td><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>no</td></tr><tr><td><code>main_click</code></td><td>L2</td><td><code>INPUT</code></td><td>yes</td></tr><tr><td><code>main_type</code></td><td>L2</td><td><code>INPUT</code></td><td>no</td></tr><tr><td><code>main_drag</code></td><td>L2</td><td><code>INPUT</code></td><td>yes</td></tr><tr><td><code>main_key</code></td><td>L2</td><td><code>INPUT</code></td><td>no</td></tr><tr><td><code>main_press</code></td><td>L3</td><td><code>VALIDATION</code></td><td>yes</td></tr><tr><td><code>main_mouse_down</code></td><td>L4</td><td><code>AUTONOMOUS</code></td><td>yes</td></tr><tr><td><code>main_mouse_up</code></td><td>L4</td><td><code>AUTONOMOUS</code></td><td>yes</td></tr><tr><td><code>main_key_down</code></td><td>L4</td><td><code>AUTONOMOUS</code></td><td>no</td></tr><tr><td><code>main_key_up</code></td><td>L4</td><td><code>AUTONOMOUS</code></td><td>no</td></tr></tbody></table><p>The level is nominal: the target can raise it depending on the reversibility of the action, but never lower it. &quot;Observed target required&quot; means that the action commits on a screen element that must be checked before acting.</p><h2 id="response-shape" tabindex="-1">Response shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response shape&quot;">​</a></h2><p>All action tools return a JSON object of one of these three shapes.</p><table tabindex="0"><thead><tr><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>{&quot;status&quot;: &quot;refused&quot;, &quot;reason&quot;: &quot;...&quot;}</code></td><td>The action is refused (ceiling, guard, human confirmation not obtained)</td></tr><tr><td><code>{&quot;status&quot;: &quot;done&quot;, &quot;result&quot;: ..., &quot;focus&quot;: ...}</code></td><td>The action was executed; <code>focus</code> is present only if a bring-to-front took place</td></tr><tr><td><code>{&quot;status&quot;: &quot;error&quot;, &quot;reason&quot;: &quot;...&quot;}</code></td><td>The organ failed to execute the action</td></tr></tbody></table><p>Preparation errors become a structured MCP error <code>{&quot;error&quot;: &quot;&lt;code&gt;&quot;, &quot;message&quot;: &quot;...&quot;}</code> and never crash the server:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_arguments</code></td><td>Invalid argument, for example <code>space=&quot;image&quot;</code> without <code>display</code></td></tr><tr><td><code>index_out_of_range</code></td><td>The <code>display</code> index does not exist</td></tr><tr><td><code>capture_failed</code></td><td>Enumerating the displays failed</td></tr><tr><td><code>motor_unavailable</code></td><td>Mains is not available on this host</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Without Accessibility, silent failures</p><p>Without the Accessibility permission, <code>main_type</code>, <code>main_key</code>, <code>main_hover</code> and <code>main_navigate</code> return <code>status: &quot;done&quot;</code> <strong>with no effect at all</strong>, and <code>main_click</code>, <code>main_press</code> and <code>main_drag</code> wait 30 seconds for a confirmation dialog. Call <a href="./diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> before concluding that a tool is broken.</p></div><h2 id="common-parameters" tabindex="-1">Common parameters <a class="header-anchor" href="#common-parameters" aria-label="Permalink to &quot;Common parameters&quot;">​</a></h2><h3 id="intent-and-reversibility" tabindex="-1">Intent and reversibility <a class="header-anchor" href="#intent-and-reversibility" aria-label="Permalink to &quot;Intent and reversibility&quot;">​</a></h3><p>Every action tool requires <code>intent</code>: a sentence declaring what you want to do, recorded in the audit log. The tools that commit also carry <code>reversible</code>: declare honestly whether the action can be undone.</p><h3 id="positionnement" tabindex="-1">Positioning <a class="header-anchor" href="#positionnement" aria-label="Permalink to &quot;Positioning {#positionnement}&quot;">​</a></h3><p>The positional tools (<code>main_click</code>, <code>main_press</code>, <code>main_hover</code>, <code>main_navigate</code>, <code>main_drag</code>, <code>main_mouse_down</code>, <code>main_mouse_up</code>) share this block:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Role</th></tr></thead><tbody><tr><td><code>space</code></td><td>string</td><td><code>&quot;global&quot;</code></td><td><code>&quot;global&quot;</code>: points of the global desktop, the unit returned by <code>vue_find</code>. <code>&quot;image&quot;</code>: pixels of a <code>vue_snapshot</code>, resolved by Daimon</td></tr><tr><td><code>display</code></td><td>integer</td><td>none</td><td>Display index; <strong>required</strong> when <code>space=&quot;image&quot;</code></td></tr><tr><td><code>max_width</code></td><td>integer</td><td><code>720</code></td><td>With <code>space=&quot;image&quot;</code>: the same cap as the snapshot. Ignored in <code>global</code></td></tr><tr><td><code>region</code></td><td>object <code>{x, y, width, height}</code></td><td>none</td><td>With <code>space=&quot;image&quot;</code>: the same region as the snapshot, in points local to the display. Ignored in <code>global</code></td></tr></tbody></table><h3 id="fenetre-cible" tabindex="-1">Target window <a class="header-anchor" href="#fenetre-cible" aria-label="Permalink to &quot;Target window {#fenetre-cible}&quot;">​</a></h3><p><code>main_click</code>, <code>main_press</code> and <code>main_drag</code> also carry this block. Empty strings and <code>0</code> mean &quot;not specified&quot;.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Role</th></tr></thead><tbody><tr><td><code>window_bundle</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Bundle identifier of the target application</td></tr><tr><td><code>window_title</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Title of the target window</td></tr><tr><td><code>window_pid</code></td><td>integer</td><td><code>0</code></td><td>Target process identifier</td></tr><tr><td><code>ensure_focus</code></td><td>boolean</td><td><code>true</code></td><td>First activates a target window that is not in front</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">What the tool description says</p><p>The MCP description of <code>main_click</code> reads &quot;window={bundle|title|pid}&quot;; the actual parameters are the three flat fields <code>window_bundle</code>, <code>window_title</code> and <code>window_pid</code> above.</p></div><h3 id="modifiers" tabindex="-1">Modifiers <a class="header-anchor" href="#modifiers" aria-label="Permalink to &quot;Modifiers&quot;">​</a></h3><p>On macOS: <code>cmd</code>, <code>shift</code>, <code>opt</code>, <code>ctrl</code>. On Windows: <code>ctrl</code>, <code>shift</code>, <code>alt</code>, <code>win</code>; <code>cmd</code> and <code>fn</code> are refused there.</p><h2 id="main-click" tabindex="-1">main_click <a class="header-anchor" href="#main-click" aria-label="Permalink to &quot;main_click {#main-click}&quot;">​</a></h2><p>Clicks on an element or a coordinate. <strong>Level L2.</strong> Refused above the ceiling.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Point to click</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>reversible</code></td><td>boolean</td><td><code>true</code></td><td>no</td><td>Whether the action can be undone</td></tr><tr><td><code>button</code></td><td>string</td><td><code>&quot;left&quot;</code></td><td>no</td><td><code>left</code>, <code>right</code> or <code>middle</code></td></tr><tr><td><code>count</code></td><td>integer</td><td><code>1</code></td><td>no</td><td><code>1</code> or <code>2</code> (double-click)</td></tr><tr><td><code>modifiers</code></td><td>list of strings</td><td><code>[]</code></td><td>no</td><td>Modifiers held during the click</td></tr><tr><td><code>role</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Role of the element (from Touché (Touch))</td></tr><tr><td><code>label</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Label of the element (from Touché)</td></tr></tbody></table><p>Plus the <a href="#positionnement">Positioning</a> and <a href="#fenetre-cible">Target window</a> blocks.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1210</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">84</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;intent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ouvrir le menu Fichier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AXMenuBarItem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Fichier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;reversible&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Pitfalls</strong>: provide <code>role</code> and <code>label</code> (read with <code>touche_probe</code>) so that Daimon can check the reversibility of the target.</p><h2 id="main-type" tabindex="-1">main_type <a class="header-anchor" href="#main-type" aria-label="Permalink to &quot;main_type {#main-type}&quot;">​</a></h2><p>Types text into the field that has focus. <strong>Level L2.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>text</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Text to type</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>reversible</code></td><td>boolean</td><td><code>true</code></td><td>no</td><td>Whether the action can be undone</td></tr><tr><td><code>role</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Role of the targeted field</td></tr><tr><td><code>label</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Label of the targeted field</td></tr></tbody></table><p><strong>Example call</strong>: <code>{ &quot;text&quot;: &quot;bonjour&quot;, &quot;intent&quot;: &quot;Remplir le champ nom&quot; }</code></p><p><strong>Pitfalls</strong></p><ul><li>The typed text is <strong>never</strong> written to the audit log.</li><li><code>main_type</code> does not choose the field: click on it first.</li><li>For a key or a shortcut, use <code>main_key</code>, not <code>main_type</code>.</li></ul><h2 id="main-key" tabindex="-1">main_key <a class="header-anchor" href="#main-key" aria-label="Permalink to &quot;main_key {#main-key}&quot;">​</a></h2><p>Sends a discrete key or a shortcut (Return, Tab, Escape, arrows, function keys, or for example <code>cmd+shift+r</code>). <strong>Level L2.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>key</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Key or combination</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>modifiers</code></td><td>list of strings</td><td><code>[]</code></td><td>no</td><td>Modifiers</td></tr><tr><td><code>count</code></td><td>integer</td><td><code>1</code></td><td>no</td><td>Number of repetitions</td></tr><tr><td><code>reversible</code></td><td>boolean</td><td><code>true</code></td><td>no</td><td>Whether the action can be undone</td></tr></tbody></table><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;r&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;modifiers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cmd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shift&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;intent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Recharger la page sans cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Pitfalls</strong>: a single character is typed with the key that the active keyboard layout uses for it. Dangerous combinations require confirmation.</p><h2 id="main-press" tabindex="-1">main_press <a class="header-anchor" href="#main-press" aria-label="Permalink to &quot;main_press {#main-press}&quot;">​</a></h2><p>Activates a committing button at (x, y) through the accessibility API (AXPress). <strong>Level L3.</strong> Targets that are not back-navigation require human confirmation.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Point of the button</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>reversible</code></td><td>boolean</td><td><strong><code>false</code></strong></td><td>no</td><td>Whether the action can be undone</td></tr><tr><td><code>role</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Role of the element</td></tr><tr><td><code>label</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Label of the element</td></tr></tbody></table><p>Plus the <a href="#positionnement">Positioning</a> and <a href="#fenetre-cible">Target window</a> blocks.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">900</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">640</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;intent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Valider l&#39;envoi du formulaire&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AXButton&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Envoyer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Pitfalls</strong>: unlike the other tools, <code>reversible</code> defaults to <code>false</code>.</p><h2 id="main-drag" tabindex="-1">main_drag <a class="header-anchor" href="#main-drag" aria-label="Permalink to &quot;main_drag {#main-drag}&quot;">​</a></h2><p>Drags from (<code>from_x</code>, <code>from_y</code>) to (<code>to_x</code>, <code>to_y</code>). <strong>Level L2.</strong> The drop destination is classified for its reversibility: dropping onto the Trash, for example, triggers the gate.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>from_x</code>, <code>from_y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Start point</td></tr><tr><td><code>to_x</code>, <code>to_y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>End point</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>button</code></td><td>string</td><td><code>&quot;left&quot;</code></td><td>no</td><td>Mouse button</td></tr><tr><td><code>reversible</code></td><td>boolean</td><td><code>true</code></td><td>no</td><td>Whether the action can be undone</td></tr></tbody></table><p>Plus the <a href="#positionnement">Positioning</a> and <a href="#fenetre-cible">Target window</a> blocks; both points go through resolution.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;from_x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;from_y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;to_x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">700</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;to_y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;intent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Déplacer la vignette&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="main-navigate" tabindex="-1">main_navigate <a class="header-anchor" href="#main-navigate" aria-label="Permalink to &quot;main_navigate {#main-navigate}&quot;">​</a></h2><p>Scrolls by a <code>scroll_y</code> value. <strong>Level L1.</strong> Reversibility is forced to true.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>scroll_y</code></td><td>integer</td><td><code>0</code></td><td>no</td><td>Amount; positive = upward</td></tr><tr><td><code>x</code>, <code>y</code></td><td>integer</td><td>none</td><td>no</td><td>Point where the scroll lands</td></tr></tbody></table><p>Plus the <a href="#positionnement">Positioning</a> block (accepted for <code>x</code>/<code>y</code>).</p><p><strong>Example call</strong>: <code>{ &quot;intent&quot;: &quot;Descendre dans la liste&quot;, &quot;scroll_y&quot;: -300, &quot;x&quot;: 700, &quot;y&quot;: 500 }</code></p><p><strong>Pitfalls</strong></p><ul><li>The amount depends on the platform: pixels on macOS; on Windows, 120 corresponds to one wheel notch.</li><li>Give a point <code>(x, y)</code> so that the scroll lands on the intended view; without a point, it applies wherever the pointer is.</li></ul><h2 id="main-hover" tabindex="-1">main_hover <a class="header-anchor" href="#main-hover" aria-label="Permalink to &quot;main_hover {#main-hover}&quot;">​</a></h2><p>Moves the pointer to (x, y) without clicking (to reveal a tooltip or a menu). <strong>Level L1.</strong> Reversibility is forced to true.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Targeted point</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr></tbody></table><p>Plus the <a href="#positionnement">Positioning</a> block.</p><h2 id="main-activate" tabindex="-1">main_activate <a class="header-anchor" href="#main-activate" aria-label="Permalink to &quot;main_activate {#main-activate}&quot;">​</a></h2><p>Brings an application or a window to the foreground. <strong>Level L1.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>bundle</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Bundle identifier</td></tr><tr><td><code>title</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>no</td><td>Window title</td></tr><tr><td><code>pid</code></td><td>integer</td><td><code>0</code></td><td>no</td><td>Process identifier</td></tr></tbody></table><p><strong>Example call</strong>: <code>{ &quot;intent&quot;: &quot;Passer sur le Finder&quot;, &quot;bundle&quot;: &quot;com.apple.finder&quot; }</code></p><h2 id="main-window-minimize" tabindex="-1">main_window_minimize <a class="header-anchor" href="#main-window-minimize" aria-label="Permalink to &quot;main_window_minimize {#main-window-minimize}&quot;">​</a></h2><p>Minimizes the foreground window of the target application, through accessibility (unaffected by a remapped shortcut, unlike Cmd+M). <strong>Level L1.</strong> Reversible: <code>main_window_show</code> restores it. Same parameters as <a href="#main-activate"><code>main_activate</code></a>.</p><h2 id="main-window-hide" tabindex="-1">main_window_hide <a class="header-anchor" href="#main-window-hide" aria-label="Permalink to &quot;main_window_hide {#main-window-hide}&quot;">​</a></h2><p>Hides the target application (unaffected by a remapped shortcut, unlike Cmd+H). <strong>Level L1.</strong> Reversible: <code>main_window_show</code> restores it. Same parameters as <a href="#main-activate"><code>main_activate</code></a>.</p><h2 id="main-window-show" tabindex="-1">main_window_show <a class="header-anchor" href="#main-window-show" aria-label="Permalink to &quot;main_window_show {#main-window-show}&quot;">​</a></h2><p>Unhides, unminimizes and raises the target application: the undo of <code>main_window_minimize</code> and <code>main_window_hide</code>. <strong>Level L1.</strong> Same parameters as <a href="#main-activate"><code>main_activate</code></a>.</p><h2 id="main-mouse-down" tabindex="-1">main_mouse_down <a class="header-anchor" href="#main-mouse-down" aria-label="Permalink to &quot;main_mouse_down {#main-mouse-down}&quot;">​</a></h2><p>Low-level primitive: presses and holds the left mouse button at (x, y). <strong>Level L4 only.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Point</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr></tbody></table><p>Plus the <a href="#positionnement">Positioning</a> block.</p><p><strong>Pitfalls</strong>: the button is released automatically after 10 seconds if <code>main_mouse_up</code> does not follow, even with no other call.</p><h2 id="main-mouse-up" tabindex="-1">main_mouse_up <a class="header-anchor" href="#main-mouse-up" aria-label="Permalink to &quot;main_mouse_up {#main-mouse-up}&quot;">​</a></h2><p>Releases the held left button, at (x, y). <strong>Level L4.</strong> Same parameters as <a href="#main-mouse-down"><code>main_mouse_down</code></a>.</p><h2 id="main-key-down" tabindex="-1">main_key_down <a class="header-anchor" href="#main-key-down" aria-label="Permalink to &quot;main_key_down {#main-key-down}&quot;">​</a></h2><p>Low-level primitive: presses and holds a key. <strong>Level L4 only.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>key</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Key</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr><tr><td><code>modifiers</code></td><td>list of strings</td><td><code>[]</code></td><td>no</td><td>Modifiers</td></tr></tbody></table><p><strong>Pitfalls</strong>: the key is released automatically after 10 seconds if <code>main_key_up</code> does not follow, even with no other call.</p><h2 id="main-key-up" tabindex="-1">main_key_up <a class="header-anchor" href="#main-key-up" aria-label="Permalink to &quot;main_key_up {#main-key-up}&quot;">​</a></h2><p>Releases a held key. <strong>Level L4.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>key</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Key</td></tr><tr><td><code>intent</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Declared intent</td></tr></tbody></table>`,90)])])}const g=e(a,[["render",n]]);export{u as __pageData,g as default};
